"use strict";function query(n){$.ajax({url:_global.root+"Postnatal/ListPostnatalEmployee",type:"GET",dataType:"html",data:{empId:$("#EmployeeId").val()===""?-1:$("#EmployeeId").val(),year:$("#Year").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#listPostnatalEmployee").html(n);floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteRequest(n,t,i){confirm("Are you sure you want to delete this item?",function(){$.post(_global.root+"postnatal/delete",{empId:n,fromDate:t,toDate:i},function(n){n.IsSuccessful?query(!1):alert(n.Message)})})}$(document).ready(function(){query(!0);$("#submit").on("click",function(){query(!1)})});